CREATE TABLE "tblIdempotencyRecord"
(
    "Id"                BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "CustomerId"        BIGINT                                  NOT NULL,
    "Operation"         VARCHAR(100)                            NOT NULL,
    "IdempotencyKey"    VARCHAR(200)                            NOT NULL,
    "RequestHash"       VARCHAR(100)                            NOT NULL,
    "DisputeExternalId" UUID                                    NOT NULL,
    "CreatedAt"         TIMESTAMP WITH TIME ZONE                NOT NULL,

    CONSTRAINT "PK_IdempotencyRecord" PRIMARY KEY ("Id"),
    CONSTRAINT "UQ_IdempotencyRecord_CustomerIdOperationIdempotencyKey" UNIQUE ("CustomerId", "Operation", "IdempotencyKey"),
    CONSTRAINT "FK_IdempotencyRecord_Customer" FOREIGN KEY ("CustomerId") REFERENCES "tblCustomer" ("Id"),
    CONSTRAINT "FK_IdempotencyRecord_Dispute" FOREIGN KEY ("DisputeExternalId") REFERENCES "tblDispute" ("ExternalId")
);
